mapper.insert:
INSERT IGNORE INTO furniture_reward (user_id, reward_stage)
SELECT #{userId}, #{rewardStage}
FROM users
WHERE id = #{userId}

mapper.select:
SELECT

FROM user_furniture uf
INNER JOIN furniture f ON f.id = uf.furniture_id
INNER JOIN furniture_categories fc ON fc.id = f.category_id
WHERE uf.user_id = #{userId}
  AND f.id = #{furnitureId}

SELECT EXISTS (
    SELECT 1
    FROM furniture f
    WHERE f.id = #{furnitureId}
      AND f.furniture_type = 'BASIC'
      AND f.active = TRUE
      AND f.unlock_score <= #{rewardStage}
      AND NOT EXISTS (
          SELECT 1
          FROM user_furniture uf
          WHERE uf.user_id = #{userId}
            AND uf.furniture_id = f.id
      )
)

SELECT EXISTS (
    SELECT 1
    FROM user_furniture
    WHERE user_id = #{userId}
      AND furniture_id = #{furnitureId}
)

mapper.update:
UPDATE user_furniture
SET is_placed = #{placed}
WHERE user_id = #{userId}
  AND furniture_id = #{furnitureId}
